@Composable
fun PesterIntervalStepper(minutes: Int, onMinutesChange: (Int) -> Unit) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(stringResource(R.string.every_label), fontWeight = FontWeight.SemiBold, fontSize = 14.sp, color = MaterialTheme.colorScheme.onSurface)
            Text(pluralStringResource(R.plurals.minutes_count, minutes, minutes), fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f))
        }
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
            val accent = MaterialTheme.colorScheme.primary
            @Composable
            fun StepButton(label: String, enabled: Boolean, onClick: () -> Unit) {
                Box(
                    modifier = Modifier
                        .size(32.dp)
                        .clip(CircleShape)
                        .background(if (enabled) accent.copy(alpha = 0.15f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
                        .then(if (enabled) Modifier.clickable(onClick = onClick) else Modifier),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        label,
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp,
                        color = if (enabled) accent else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.3f)
                    )
                }
            }
            StepButton("-", enabled = minutes > PESTER_INTERVAL_MIN_MINUTES) {
                onMinutesChange((minutes - PESTER_INTERVAL_STEP_MINUTES).coerceAtLeast(PESTER_INTERVAL_MIN_MINUTES))
            }
            Text("$minutes", fontWeight = FontWeight.Bold, fontSize = 14.sp, modifier = Modifier.width(28.dp), textAlign = TextAlign.Center)
            StepButton("+", enabled = minutes < PESTER_INTERVAL_MAX_MINUTES) {
                onMinutesChange((minutes + PESTER_INTERVAL_STEP_MINUTES).coerceAtMost(PESTER_INTERVAL_MAX_MINUTES))
            }
        }
    }
}
